                "groupKey": key,
                "grouper": grouper,
                "groupers": groupers,
                "label": key,
                "rootProperty": me.getItemRoot(),
                "sorters": source.getSorters(),
                "autoSort": autoSort,
                "autoGroup": me.getAutoGroup(),
