    "implicitModel": "Ext.data.TreeModel",

    /**
     * @cfg {String} groupField
     * @hide
     */
    "groupField": null,

    /**
     * @cfg {String} groupDir
     * @hide
     */
    "groupDir": null,

    /**
     * @cfg {Object/Ext.util.Grouper} grouper
     * @hide
     */
    "grouper": null,
