            var me = this;
            if ( oldStore ) {
                Ext.destroy( me.storeListeners );
            }
            if ( store ) {
                me.storeListeners = store.on( Ext.apply(
                    {
                        "scope": me,
                        "destroyable": true,
                    },
                    me.getStoreEventListeners()
                ) );
                me.refreshData();
            }
