                range[ 0 ] = range[ 0 ].length === 0
                    ? -Infinity
                    : Number.parseFloat( range[ 0 ] );
                range[ 1 ] = range[ 1 ].length === 0
                    ? Infinity
                    : Number.parseFloat( range[ 1 ] );
                range[ 2 ] = map[ key ];
                rangelist.push( range );
