    "extend": Ext.field.Text,
    "xtype": "textareafield",
    "alternateClassName": "Ext.form.TextArea",
    "config": {

        /**
         * @cfg autoCapitalize
         * @inheritdoc
         */
        "autoCapitalize": false,

        /**
         * @cfg {Number} maxRows
         * The maximum number of lines made visible by the input.
         */
        "maxRows": null,

        /**
         * @cfg clearable
         * @inheritdoc
         */
        "clearable": false,
    },

    /**
     * @property tag
     * @inheritdoc
     */
    "tag": "textarea",

    /**
     * @property classCls
     * @inheritdoc
     */
    "classCls": Ext.baseCSSPrefix + "textareafield",
    "initialize": function () {
        this.callParent();
        this.ariaEl.set( {
            "aria-multiline": true,
        } );
    },
