            daysInMonth,
            day,
            month,
            year,
            item,
            i;
        for ( i = 0; i < ln; i++ ) {
            item = items[ i ];
            if ( item.isSlot ) {
                values[ item.getName() ] = item.getValue( useDom );
            }
        }

        // if all the slots return null, we should not return a date
        if ( values.year === null && values.month === null && values.day === null ) {
            return null;
        }
        year = Ext.isNumber( values.year )
            ? values.year
            : 1;
        month = Ext.isNumber( values.month )
            ? values.month
            : 1;
        day = Ext.isNumber( values.day )
            ? values.day
            : 1;
