            hoveredNodeEl = Ext.dd.Manager.getTargetEl( info ),
            isDragSuspended = targetEl.isSuspended( "drag" ) || targetEl.isSuspended( "longpress" );
        if ( isDragSuspended || targetCmp.isDragColumn || targetCmp.getDraggable() === false || targetCmp.isGroupsColumn || Ext.fly( info.eventTarget ).hasCls( me.resizerCls ) || Ext.fly( hoveredNodeEl ).hasCls( me.maskCls ) ) {
            return false;
        }
        info.setData( "column", targetCmp );
        info.setData( "panel", me.view );
        info.setData( "grid", me.grid );
        me.callParent( [ info ] );
