Ext.define( "Ext.util.TranslatableList", {
    "extend": Ext.util.translatable.Abstract,
    "config": {
        "items": [],
    },
    "applyItems": function ( items ) {
        return Ext.Array.from( items );
    },
    "doTranslate": function ( x, y ) {
        var items = this.getItems(),
            offset = 0,
            i,
            ln,
            item,
            translateY;
        for ( i = 0, ln = items.length; i < ln; i++ ) {
            item = items[ i ];
            if ( item && !item._list_hidden ) {
                translateY = y + offset;
                offset += item.$height;
                item.translate( 0, translateY );
            }
        }
    },
} );

/**
 * @class Ext.util.translatable.Component
 * @private
 */
Ext.define( "Ext.util.translatable.Component", {
    "extend": Ext.util.translatable.CssTransform,
    "alias": "translatable.component",

    // also configures Factoryable
    "config": {
        "component": null,
    },
    "doTranslate": function ( x, y ) {
        var component = this.getComponent();
        if ( component.getFloated() ) {
            component.setX( x );
            component.setY( y );
        }
        else if ( component.isPositioned() ) {
            component.setLeft( x );
            component.setTop( y );
        }
        else {
            this.callParent( [ x, y ] );
        }
    },
    "syncPosition": function () {
        var component = this.getComponent(),
            result;
        if ( component.getFloated() ) {
            result = [ component.getX(), component.getY() ];
        }
        else if ( component.isPositioned() ) {
            result = [ component.getLeft(), component.getTop() ];
        }
        else {
            result = this.callParent();
        }
        this.x = result[ 0 ];
        this.y = result[ 1 ];
        return result;
    },
} );

